m['trial_ends_at']?.toString()??''),expired=!full&&end!=null&&DateTime.now().toUtc().isAfter(end.toUtc());return InkWell(onTap:()async{await Navigator.push(context,MaterialPageRoute(builder:(_)=>EnhancedChatScreen(matchId:m['id'].toString(),profile:p)));if(mounted)reload();},borderRadius:BorderRadius.circular(24),child:Container(padding:const EdgeInsets.all(15),decoration:BoxDecoration(color:ui.OpenApp.soft,borderRadius:BorderRadius.circular(24)),child:Row(children:[CircleAvatar(radius:28,backgroundColor:Colors.white,backgroundImage:has?NetworkImage(avatar):null,child:has?null:const Icon(Icons.person_rounded)),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text((p['display_name']??'Open kullanıcısı').toString(),style:const TextStyle(fontSize:17,fontWeight:FontWeight.w900)),const SizedBox(height:4),Text(expired?'🔒 Kalan 2 soruyu cevapla':full?(last.isEmpty?'Tam kilit açıldı 🔓':(last['body']??'').toString()):(last.isEmpty?'15 dk ilk sohbet':(last['body']??'').toString()),maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(color:expired?ui.OpenApp.ink:ui.OpenApp.muted,fontWeight:expired?FontWeight.w800:FontWeight.w500))])),if(unread>0)Container(padding:const EdgeInsets.all(7),decoration:const BoxDecoration(color:ui.OpenApp.lime,shape:BoxShape.circle),child:Text('$unread',style:const TextStyle(fontWeight:FontWeight.w900)))else const Icon(Icons.chevron_right_rounded)])));});}))])));}
