class _EnhancedChatScreenState extends State<EnhancedChatScreen>{final input=TextEditingController(),scroll=ScrollController();bool busy=false,loading=true,full=false;DateTime? ends;Timer? timer;Duration left=Duration.zero;@override void initState(){super.initState();_init();}@override void dispose(){timer?.cancel();input.dispose();scroll.dispose();super.dispose();}Future<void> _init()async{try{final s=await OpenBackend.instance.startTrialChat(widget.matchId);ends=DateTime.tryParse(s['trial_ends_at']?.toString()??'');full=s['fully_unlocked_at']!=null;await OpenBackend.instance.markMessagesRead(widget.matchId);_tick();timer=Timer.periodic(const Duration(seconds:1),(_)=>_tick());}finally{if(mounted)setState(()=>loading=false);}}void _tick(){if(full){left=Duration.zero;return;}final e=ends;if(e==null)return;final d=e.toUtc().difference(DateTime.now().toUtc());if(mounted)setState(()=>left=d.isNegative?Duration.zero:d);}bool get locked=>!full&&left==Duration.zero&&!loading;String get clock=>'${left.inMinutes.toString().padLeft(2,'0')}:${(left.inSeconds%60).toString().padLeft(2,'0')}';Future<void> send()async{final text=input.text.trim();if(text.isEmpty||busy||locked)return;input.clear();setState(()=>busy=true);try{await OpenBackend.instance.sendMessage(widget.matchId,text);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text('$e')));}finally{if(mounted)setState(()=>busy=false);}}@override Widget build(BuildContext context){final name=(widget.profile['display_name']??'Open kullanıcısı').toString(),me=OpenBackend.instance.userId;return Scaffold(backgroundColor:Colors.white,appBar:AppBar(backgroundColor:Colors.white,title:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text(name,style:const TextStyle(fontWeight:FontWeight.w900)),Text(full?'Tam kilit açık 🔓':locked?'Sohbet kilitlendi 🔒':'İlk sohbet · $clock',style:TextStyle(fontSize:12,fontWeight:FontWeight.w700,color:locked?Colors.redAccent:ui.OpenApp.muted))])),body:SafeArea(child:Column(children:[if(!full&&!locked)LinearProgressIndicator(value:left.inSeconds/900,minHeight:4,backgroundColor:ui.OpenApp.soft,color:ui.OpenApp.lime),Expanded(child:StreamBuilder<List<Map<String,dynamic>>>(stream:OpenBackend.instance.messageStream(widget.matchId),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());final msgs=s.data!;if(msgs.isEmpty)return const Center(child:Text('15 dakikalık ilk sohbetiniz başladı ✨',style:TextStyle(color:ui.OpenApp.muted)));return ListView.builder(controller:scroll,padding:const EdgeInsets.all(18),itemCount:msgs.length,itemBuilder:(_,i){final m=msgs[i],mine=m['sender_id']==me;return Align(alignment:mine?Alignment.centerRight:Alignment.centerLeft,child:Container(constraints:const BoxConstraints(maxWidth:300),margin:const EdgeInsets.only(bottom:9),padding:const EdgeInsets.symmetric(horizontal:15,vertical:11),decoration:BoxDecoration(color:mine?ui.OpenApp.lime:ui.OpenApp.soft,borderRadius:BorderRadius.circular(20)),child:Text((m['body']??'').toString())));});})),if(locked)_LockedPanel(matchId:widget.matchId,profile:widget.profile,onUnlocked:(){setState((){full=true;});})else Padding(padding:const EdgeInsets.fromLTRB(14,8,14,14),child:Row(children:[Expanded(child:TextField(controller:input,textInputAction:TextInputAction.send,onSubmitted:(_)=>send(),decoration:InputDecoration(hintText:full?'Mesaj yaz...':'İlk sohbet · $clock'))),const SizedBox(width:8),IconButton.filled(onPressed:busy?null:send,style:IconButton.styleFrom(backgroundColor:ui.OpenApp.lime,foregroundColor:ui.OpenApp.ink),icon:const Icon(Icons.arrow_upward_rounded))]))])));}}
