class _UnlockQuestionsScreenState extends State<UnlockQuestionsScreen>{bool loading=true,busy=false;List<Map<String,dynamic>> questions=[],answers=[];final ctrls=<String,TextEditingController>{};@override void initState(){super.initState();_load();}@override void dispose(){for(final c in ctrls.values)c.dispose();super.dispose();}Future<void> _load()async{final other=widget.otherProfile['id'].toString();questions=await OpenBackend.instance.remainingQuestions(widget.matchId,other);answers=await OpenBackend.instance.unlockAnswers(widget.matchId);for(final q in questions){ctrls[q['id'].toString()]=TextEditingController();}if(mounted)setState(()=>loading=false);}Future<void> _submit()async{if(ctrls.values.any((c)=>c.text.trim().isEmpty)){ScaffoldMessenger.of(context).showSnackBar(const SnackBar(content:Text('İki soruyu da cevapla.')));return;}setState(()=>busy=true);try{for(final q in questions){await OpenBackend.instance.answerUnlockQuestion(widget.matchId,q['id'].toString(),ctrls[q['id'].toString()]!.text);}answers=await OpenBackend.instance.unlockAnswers(widget.matchId);if(!mounted)return;setState((){});await _decision();}finally{if(mounted)setState(()=>busy=false);}}Future<void> _decision()async{final yes=await showDialog<bool>(context:context,barrierDismissible:false,builder:(c)=>AlertDialog(icon:const Icon(Icons.key_rounded,size:42,color:ui.OpenApp.ink),title:const Text('Cevaplar hoşuna gitti mi?'),content:const Text('İkiniz de devam etmek isterseniz profil ve sohbet tamamen açılır.'),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Burada bitirelim')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Devam etmek istiyorum ❤️'))]))??false;final state=await OpenBackend.instance.setUnlockDecision(widget.matchId,yes);if(!mounted)return;if(!yes){Navigator.pop(context,false);return;}if(state['fully_unlocked_at']!=null){await showDialog(context:context,builder:(c)=>AlertDialog(icon:const Icon(Icons.lock_open_rounded,size:48),tit